### How does pagination work in JPA and Spring Data?

JPA provides two levels of pagination. The low-level approach uses `EntityManager` query methods directly. The high-level approach uses Spring Data's `Pageable` interface.

```java
package com.bank.service;

import com.bank.model.Trade;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
public class TradePaginationService {

    @PersistenceContext
    private EntityManager em;

    @Transactional(readOnly = true)
    public List<Trade> findTradesPage(int offset, int limit) {
        return em.createQuery(
                "SELECT t FROM Trade t ORDER BY t.amount DESC", Trade.class)
            .setFirstResult(offset)   // OFFSET: skip first N rows
            .setMaxResults(limit)     // LIMIT: take N rows
            .getResultList();
        // Generates: SELECT ... FROM trades ORDER BY amount DESC
        //            OFFSET 80 LIMIT 20
    }
}
```

### How does Spring Data Pageable work?

Spring Data provides `PageRequest.of(page, size, Sort)` to encapsulate pagination and sorting. Pass it to any repository method that accepts `Pageable`.

```java
package com.bank.repository;

import com.bank.model.Trade;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Slice;
import org.springframework.data.domain.Sort;
import org.springframework.data.jpa.repository.JpaRepository;
import java.util.List;

public interface TradeRepository extends JpaRepository<Trade, String> {
    Page<Trade> findByStatus(String status, Pageable pageable);
    Slice<Trade> findByAccountId(String accountId, Pageable pageable);
    List<Trade> findBySymbol(String symbol, Sort sort);  // sorting only
}
```

```java
package com.bank.controller;

import com.bank.model.Trade;
import com.bank.repository.TradeRepository;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.web.bind.annotation.*;

@RestController
public class TradeController {

    private final TradeRepository tradeRepo;

    public TradeController(TradeRepository tradeRepo) {
        this.tradeRepo = tradeRepo;
    }

    @GetMapping("/trades")
    public Page<Trade> getTrades(
        @RequestParam(defaultValue = "0") int page,
        @RequestParam(defaultValue = "20") int size
    ) {
        Pageable pageable = PageRequest.of(page, size,
            Sort.by(Sort.Direction.DESC, "amount"));
        return tradeRepo.findByStatus("SETTLED", pageable);
    }
}
```

### What is the difference between Page and Slice?

`Page<T>` fires two queries: one for the data and one COUNT for the total. `Slice<T>` fires only one query with LIMIT N+1 – the extra row determines `hasNext`.

| Feature | Page<T> | Slice<T> |
|---------|---------|----------|
| Count query | Yes (SELECT COUNT) | No |
| Total elements | `getTotalElements()` | Not available |
| Total pages | `getTotalPages()` | Not available |
| Has next | `hasNext()` | `hasNext()` |
| SQL queries | 2 (data + count) | 1 (data with LIMIT+1) |
| Use case | Numbered pagination | Infinite scroll |

```java
package com.bank.service;

import com.bank.model.Trade;
import com.bank.repository.TradeRepository;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Slice;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class TradeListingService {

    private final TradeRepository tradeRepo;

    public TradeListingService(TradeRepository tradeRepo) {
        this.tradeRepo = tradeRepo;
    }

    // Page: for numbered pagination ("Page 3 of 25")
    @Transactional(readOnly = true)
    public Page<Trade> getSettledTrades(int page, int size) {
        Page<Trade> result = tradeRepo.findByStatus("SETTLED",
            PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, "amount")));
        // Fires TWO queries:
        // 1. SELECT * FROM trades WHERE status='SETTLED' ORDER BY amount DESC LIMIT 20 OFFSET 40
        // 2. SELECT COUNT(*) FROM trades WHERE status='SETTLED'

        result.getContent();       // List<Trade> for this page
        result.getTotalElements(); // 500 total matching trades
        result.getTotalPages();    // 25 pages
        result.getNumber();        // 2 (current page, 0-based)
        result.isFirst();          // false
        result.hasNext();          // true
        return result;
    }

    // Slice: for infinite scroll ("Load more")
    @Transactional(readOnly = true)
    public Slice<Trade> getTradesForScroll(String accountId, int page) {
        Slice<Trade> slice = tradeRepo.findByAccountId(accountId,
            PageRequest.of(page, 20));
        // Fires ONE query: SELECT ... LIMIT 21
        // Returns 20 rows, uses 21st to set hasNext
        // NO count query!

        slice.getContent();    // List<Trade>
        slice.hasNext();       // true/false
        slice.hasPrevious();   // true/false
        return slice;
    }
}
```

### How does Sort work?

Sort specifies ordering for repository methods. You can compose multi-field sorts using `.and()` or by passing multiple `Order` objects.

```java
package com.bank.service;

import org.springframework.data.domain.Sort;
import org.springframework.data.domain.Sort.Order;

public class SortExamples {

    public void sortDemo() {
        // Single field, descending
        Sort sort1 = Sort.by(Sort.Direction.DESC, "amount");
        // ORDER BY amount DESC

        // Multi-field with .and()
        Sort sort2 = Sort.by(Sort.Direction.DESC, "amount")
            .and(Sort.by(Sort.Direction.ASC, "tradeId"));
        // ORDER BY amount DESC, trade_id ASC

        // Multi-field with Order objects
        Sort sort3 = Sort.by(Order.desc("settlementDate"), Order.asc("tradeId"));
        // ORDER BY settlement_date DESC, trade_id ASC

        // Null handling
        Sort sort4 = Sort.by(Order.desc("amount").nullsLast());
        // ORDER BY amount DESC NULLS LAST
    }
}
```

### What are common mistakes with pagination?

The most common mistake is using Page when you do not need the total count. The COUNT query can be expensive on large tables with complex WHERE clauses.

```java
package com.bank.service;

import com.bank.model.Trade;
import com.bank.repository.TradeRepository;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Slice;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaginationMistakeDemo {

    private final TradeRepository tradeRepo;

    public PaginationMistakeDemo(TradeRepository tradeRepo) {
        this.tradeRepo = tradeRepo;
    }

    // WRONG: using Page for infinite scroll (unnecessary COUNT)
    @Transactional(readOnly = true)
    public Page<Trade> wrongInfiniteScroll(String accountId, int page) {
        return tradeRepo.findByStatus("SETTLED", PageRequest.of(page, 20));
        // Fires COUNT query every time. Wasted for infinite scroll.
    }

    // CORRECT: use Slice for infinite scroll
    @Transactional(readOnly = true)
    public Slice<Trade> correctInfiniteScroll(String accountId, int page) {
        return tradeRepo.findByAccountId(accountId, PageRequest.of(page, 20));
        // No COUNT query. 50% fewer queries.
    }
}
```

### What should a senior engineer know?

- **Window functions for row count.** Instead of two queries (data + COUNT), PostgreSQL can compute the total in one query: `SELECT *, COUNT(*) OVER() AS total FROM trades WHERE status = 'SETTLED' LIMIT 20 OFFSET 40`. Spring Data does not generate this automatically, but you can use a native query.
- **Offset pagination degrades linearly.** Page 10,000 means the database scans and discards 200,000 rows before returning 20. Always offer keyset pagination for large tables.
- **Consistent sort order.** If two trades have the same amount, the database may return them in different orders on different pages. Always include a unique column (tradeId) as a tiebreaker: `Sort.by(Order.desc("amount"), Order.asc("tradeId"))`.
- **Spring Data Web support.** Add `@PageableDefault(size = 20, sort = "amount", direction = DESC)` to controller parameters. Spring resolves `?page=0&size=20&sort=amount,desc` from query parameters automatically.

```java
package com.bank.controller;

import com.bank.model.Trade;
import com.bank.repository.TradeRepository;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.web.PageableDefault;
import org.springframework.data.domain.Sort;
import org.springframework.web.bind.annotation.*;

@RestController
public class TradePageController {

    private final TradeRepository tradeRepo;

    public TradePageController(TradeRepository tradeRepo) {
        this.tradeRepo = tradeRepo;
    }

    // Spring resolves Pageable from query params: ?page=0&size=20&sort=amount,desc
    @GetMapping("/api/v1/trades")
    public Page<Trade> list(
        @PageableDefault(size = 20, sort = "amount",
                         direction = Sort.Direction.DESC) Pageable pageable
    ) {
        return tradeRepo.findByStatus("SETTLED", pageable);
    }
}
```

### How does native query pagination work?

Native queries require a separate `countQuery` when returning `Page<T>`. Spring Data cannot derive the count query from raw SQL.

```java
package com.bank.repository;

import com.bank.model.Trade;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface TradeRepository extends JpaRepository<Trade, String> {

    @Query(value = "SELECT * FROM trades WHERE status = :status",
           countQuery = "SELECT COUNT(*) FROM trades WHERE status = :status",
           nativeQuery = true)
    Page<Trade> findByStatusNative(@Param("status") String status,
                                   Pageable pageable);
    // countQuery is REQUIRED for Page with native queries!
}
```

### When should you use keyset pagination instead?

For deep pages (page 10,000 of a million-row table), offset pagination is slow because the database scans and discards all preceding rows. Keyset pagination uses a WHERE condition with the last seen ID to seek directly.

```java
package com.bank.repository;

import com.bank.model.Trade;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface TradeRepository extends JpaRepository<Trade, String> {

    @Query("SELECT t FROM Trade t WHERE t.tradeId > :lastId ORDER BY t.tradeId")
    List<Trade> findNextPage(@Param("lastId") String lastSeenId, Pageable pageable);
    // Offset: OFFSET 200000 LIMIT 20 (scans 200K rows)
    // Keyset: WHERE trade_id > 'TRD-200000' LIMIT 20 (index seek, instant)
}
```

```text
Offset pagination (deep page):
  SELECT * FROM trades ORDER BY trade_id OFFSET 200000 LIMIT 20
  Time: 2.5 seconds (scans 200,000 rows)

Keyset pagination:
  SELECT * FROM trades WHERE trade_id > 'TRD-200000' ORDER BY trade_id LIMIT 20
  Time: 2ms (index seek to exact position)
```
